22	  { id: "vpx", label: "vp", launcher: "vpx ", color: "#6b77f8", icon: "vite-plus" },
23	  { id: "pnpm", label: "pnpm", launcher: "pnpm dlx ", color: "#F69220", icon: "pnpm" },
24	  { id: "deno", label: "deno", launcher: "deno run npm:", color: "#70ffaf", icon: "deno" },
25	  { id: "bun", label: "bun", launcher: "bunx ", color: "#ff2e97", icon: "bun" },
26	  { id: "npm", label: "npm", launcher: "npx ", color: "#CB3837", icon: "npm" },
27	  { id: "yarn", label: "yarn", launcher: "yarn dlx ", color: "#2C8EBB", icon: "yarn" },
28	];
29	
30	const aiProviderOptions: AiProviderOption[] = [
31	  { id: "claude", label: "claude", launcher: "claude ", color: "#D97757" },
32	  { id: "gemini", label: "gemini", launcher: "gemini ", color: "#4785ff" },
33	];
34	
35	const activePmIndex = ref(0);
36	const activePm = computed(() => pmOptions[activePmIndex.value]);
37	const activeAiProviderIndex = ref(0);
38	const activeAiProvider = computed(() => aiProviderOptions[activeAiProviderIndex.value]);
39	const activeSurface = ref<"terminal" | "agent">("terminal");
40	
41	const BASE_COMMAND = "create-pantoken-app";
42	const AGENT_PROMPT = "/scaffold-pantoken";
43	
44	function baseCommandFor(): string {
45	  return BASE_COMMAND;
46	}
47	
48	const activeBaseCommand = computed(() => baseCommandFor());
49	/** The full icon+launcher+base sequence length for a given pm (not just the active one). */
50	function totalLengthFor(pm: PmOption): number {
51	  return (pm.icon ? 1 : 0) + pm.launcher.length + baseCommandFor().length;
52	}
53	// The icon reveals/hides as the first "character" of the line, typed before the launcher and
54	// backspaced last.
