70	  activeBaseCommand.value.slice(
71	    0,
72	    Math.max(0, charCount.value - iconOffset.value - activePm.value.launcher.length),
73	  ),
74	);
75	const visibleCommand = computed(() => `${typedLauncher.value}${typedBase.value}`);
76	
