81	const terminalPlatform = ref<TerminalPlatform>("linux");
82	let timeoutId: ReturnType<typeof setTimeout> | undefined;
83	
84	const TYPE_MS = 70;
85	const DELETE_MS = 40;
86	const HOLD_MS = 1400;
87	// A touch longer than HOLD_MS so the new word's arrival reads as a deliberate beat, not a rebound.
88	const START_HOLD_MS = 1700;
89	
90	const cursorBlink = ref(false);
91	let blinkTimeoutId: ReturnType<typeof setTimeout> | undefined;
92	let copyFeedbackTimeoutId: ReturnType<typeof setTimeout> | undefined;
93	const BLINK_MS = 600;
