95	// Plays a few blinks of the cursor without touching the type/pause/delete timing — used to mark the
96	// start of a new word and the moment a word finishes typing, before it starts backspacing.
97	function beatBlink() {
98	  cursorBlink.value = false;
99	  clearTimeout(blinkTimeoutId);
100	  requestAnimationFrame(() => {
101	    cursorBlink.value = true;
102	    blinkTimeoutId = setTimeout(() => {
103	      cursorBlink.value = false;
104	    }, BLINK_MS);
105	  });
106	}
