108	// Drives the idle/type/pause/backspace loop with a chained setTimeout (each phase has its own
109	// delay), rather than a fixed-period interval — resuming after a pause just reschedules from where
110	// it left off.
111	function scheduleNext() {
112	  clearTimeout(timeoutId);
113	  if (isPaused.value || reducedMotion.value) return;
114	
115	  if (phase.value === "idle") {
116	    timeoutId = setTimeout(() => {
117	      activePmIndex.value = (activePmIndex.value + 1) % pmOptions.length;
118	      phase.value = "typing";
119	      scheduleNext();
120	    }, START_HOLD_MS);
121	    return;
122	  }
123	
124	  if (phase.value === "typing") {
125	    if (charCount.value < totalLength.value) {
126	      timeoutId = setTimeout(() => {
127	        charCount.value++;
128	        scheduleNext();
129	      }, TYPE_MS);
130	    } else {
131	      phase.value = "paused";
132	      beatBlink();
133	      scheduleNext();
134	    }
135	    return;
136	  }
137	
138	  if (phase.value === "paused") {
139	    timeoutId = setTimeout(() => {
140	      phase.value = "deleting";
141	      scheduleNext();
142	    }, HOLD_MS);
143	    return;
144	  }
145	
146	  // deleting
147	  if (charCount.value > 0) {
148	    timeoutId = setTimeout(() => {
149	      charCount.value--;
150	      scheduleNext();
151	    }, DELETE_MS);
152	  } else {
153	    // Stay on the just-erased pm (and its cursor color) through the idle blink; the next pm and its
154	    // color/icon only take over once typing actually starts.
155	    phase.value = "idle";
156	    beatBlink();
157	    scheduleNext();
158	  }
159	}
