161	function detectTerminalPlatform(): TerminalPlatform {
162	  const nav = window.navigator as Navigator & {
163	    userAgentData?: { platform?: string };
164	  };
165	  const uaPlatform = nav.userAgentData?.platform ?? "";
166	  const classicPlatform = nav.platform ?? "";
167	  const userAgent = nav.userAgent ?? "";
168	  const source = `${uaPlatform} ${classicPlatform} ${userAgent}`.toLowerCase();
169	
170	  if (/(mac|iphone|ipad|ipod)/.test(source)) return "mac";
171	  if (/(win|windows)/.test(source)) return "windows";
172	  return "linux";
173	}
