214	async function copyText(value: string, onSuccess: () => void) {
215	  if (!value) return;
216	
217	  try {
218	    if (navigator.clipboard?.writeText) {
219	      await navigator.clipboard.writeText(value);
220	    } else {
221	      const probe = document.createElement("textarea");
222	      probe.value = value;
223	      probe.setAttribute("readonly", "true");
224	      probe.style.position = "fixed";
225	      probe.style.opacity = "0";
226	      document.body.appendChild(probe);
227	      probe.select();
228	      document.execCommand("copy");
229	      document.body.removeChild(probe);
230	    }
231	
232	    onSuccess();
233	  } catch {
234	    // Ignore clipboard failures in restricted contexts.
235	  }
236	}
