1	<script setup lang="ts">
2	import { computed, onMounted, onUnmounted, ref } from "vue";
3	import { useData } from "vitepress";
4	import { useCommandCycle, type CommandCycleOption } from "./useCommandCycle";
5	import CommandCycleRow from "./CommandCycleRow.vue";
6	import { GET_STARTED_TABS_DEFAULTS, type GetStartedTabsStrings } from "../get-started";
7	
8	const pmOptions: CommandCycleOption[] = [
9	  { id: "vpx", label: "vp", launcher: "vpx ", color: "#6b77f8", icon: "vite-plus" },
10	  { id: "pnpm", label: "pnpm", launcher: "pnpm dlx ", color: "#F69220", icon: "pnpm" },
11	  {
12	    id: "deno",
13	    label: "deno",
14	    launcher: "deno run npm:",
15	    color: "#00b84d",
16	    darkColor: "#70ffaf",
17	    icon: "deno",
18	  },
19	  { id: "bun", label: "bun", launcher: "bunx ", color: "#ff2e97", icon: "bun" },
20	  { id: "npm", label: "npm", launcher: "npx ", color: "#CB3837", icon: "npm" },
21	  { id: "yarn", label: "yarn", launcher: "yarn dlx ", color: "#2C8EBB", icon: "yarn" },
22	];
23	
24	const aiProviderOptions: CommandCycleOption[] = [
25	  { id: "claude", label: "claude", launcher: "claude ", color: "#D97757", icon: "claudecode" },
26	  { id: "gemini", label: "gemini", launcher: "gemini ", color: "#4785ff", icon: "googlegemini" },
27	];
28	
29	const activeSurface = ref<"terminal" | "agent">("terminal");
30	const terminalHovered = ref(false);
31	const terminalTextHovered = ref(false);
32	const agentHovered = ref(false);
33	const agentTextHovered = ref(false);
34	
35	const BASE_COMMAND = "create-pantoken-app";
36	const AGENT_PROMPT = "/scaffold-pantoken";
37	
38	type DocsThemeWithGetStartedTabs = {
39	  getStartedTabs?: GetStartedTabsStrings;
40	};
41	const { theme } = useData<DocsThemeWithGetStartedTabs>();
42	const getStartedTabs = computed<GetStartedTabsStrings>(
43	  () => theme.value.getStartedTabs ?? GET_STARTED_TABS_DEFAULTS,
44	);
45	
46	const isPaused = ref(false);
47	const reducedMotion = ref(false);
48	
49	const TYPE_MS = 70;
50	const DELETE_MS = 40;
51	const HOLD_MS = 1400;
52	// A touch longer than HOLD_MS so the new word's arrival reads as a deliberate beat, not a rebound.
53	const START_HOLD_MS = 1700;
54	const BLINK_MS = 600;
55	
56	const timings = {
57	  typeMs: TYPE_MS,
58	  deleteMs: DELETE_MS,
59	  holdMs: HOLD_MS,
60	  startHoldMs: START_HOLD_MS,
61	  blinkMs: BLINK_MS,
62	};
63	
64	const terminalCycle = useCommandCycle({
65	  options: pmOptions,
66	  suffix: BASE_COMMAND,
67	  isPaused,
68	  reducedMotion,
69	  timings,
70	});
71	
72	const agentCycle = useCommandCycle({
73	  options: aiProviderOptions,
74	  suffix: AGENT_PROMPT,
75	  isPaused,
76	  reducedMotion,
77	  timings,
78	});
79	
80	onMounted(() => {
81	  reducedMotion.value = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
82	  terminalCycle.start();
83	  agentCycle.start();
84	});
85	
86	onUnmounted(() => {
87	  terminalCycle.stop();
88	  agentCycle.stop();
89	});
90	
91	// Hovering/focusing mid-type or mid-backspace jumps straight to the fully-typed line, not wherever
92	// the animation happened to be — pausing shouldn't leave a half-typed or half-erased command visible.
93	function pause() {
94	  isPaused.value = true;
95	  terminalCycle.pauseAtFull();
96	  agentCycle.pauseAtFull();
97	}
98	function resume() {
99	  isPaused.value = false;
100	  terminalCycle.resume();
101	  agentCycle.resume();
102	}
103	
104	function enterTerminal() {
105	  terminalHovered.value = true;
106	  pause();
107	}
108	
109	function leaveTerminal() {
110	  terminalHovered.value = false;
111	  terminalTextHovered.value = false;
112	  resume();
113	}
114	
115	function enterAgent() {
116	  agentHovered.value = true;
117	  pause();
118	}
119	
120	function leaveAgent() {
121	  agentHovered.value = false;
122	  agentTextHovered.value = false;
123	  resume();
124	}
125	</script>
126	
127	<template>
