143	        :class="{ 'is-active': activeSurface === 'agent' }"
144	        :aria-selected="activeSurface === 'agent'"
145	        aria-label="Agent shell mode"
146	        @click="activeSurface = 'agent'"
147	      >
148	        <span class="instui-screen-reader-content">{{ getStartedTabs.aiInstall }}</span>
149	      </button>
150	    </div>
151	
152	    <div class="gs-started__stage" :class="{ '-agent': activeSurface === 'agent' }">
153	      <div class="gs-started__flipper">
154	        <div class="gs-started__face gs-started__face--terminal">
155	          <div
