158	            @mouseleave="leaveTerminal"
159	            @focusin="pause"
160	            @focusout="resume"
161	          >
162	            <div class="gs-terminal__chrome" aria-hidden="true">
163	              <span class="gs-terminal__dot -red" />
164	              <span class="gs-terminal__dot -yellow" />
165	              <span class="gs-terminal__dot -green" />
166	            </div>
167	
168	            <div class="gs-terminal__body">
169	              <div
170	                class="gs-terminal__command-zone"
171	                @mouseenter="terminalTextHovered = true"
172	                @mouseleave="terminalTextHovered = false"
173	              >
174	                <pre><code
175	                    ><CommandCycleRow
176	                      :cycle="terminalCycle"
177	                      :options="pmOptions"
178	                      copy-label="Copy command"
179	                      :copied-label="getStartedTabs.copied"
180	                      suffix-variant="terminal"
181	                      :copy-visible="terminalHovered"
182	                      :popover-visible="terminalHovered && terminalTextHovered"
183	                      :auto-open-on-row-hover="false"
184	                      popover-placement="below"
185	                    /></code
186	                  ></pre>
187	              </div>
188	            </div>
189	          </div>
190	        </div>
191	
192	        <div class="gs-started__face gs-started__face--agent">
193	          <div
194	            class="gs-terminal gs-agent-terminal"
195	            @mouseenter="enterAgent"
196	            @mouseleave="leaveAgent"
197	            @focusin="pause"
198	            @focusout="resume"
199	          >
200	            <div class="gs-terminal__chrome" aria-hidden="true">
201	              <span class="gs-terminal__dot -red" />
202	              <span class="gs-terminal__dot -yellow" />
203	              <span class="gs-terminal__dot -green" />
204	            </div>
205	
206	            <div class="gs-terminal__body gs-agent-terminal__body">
207	              <div class="instui-agent-shell gs-agent-shell">
208	                <div class="gs-agent-shell__prompt-muted" aria-hidden="true">
209	                  <span class="instui-icon -icon-sparkles" aria-hidden="true"></span>
210	                  <span>What would you like to build today?</span>
211	                </div>
212	                <div class="gs-agent">
213	                  <div class="gs-agent__body" aria-hidden="true"></div>
214	
215	                  <div
216	                    class="gs-agent__input-wrap"
217	                    @mouseenter="agentTextHovered = true"
218	                    @mouseleave="agentTextHovered = false"
219	                  >
220	                    <CommandCycleRow
221	                      :cycle="agentCycle"
