223	                      copy-label="Copy agent input"
224	                      :copied-label="getStartedTabs.copied"
225	                      suffix-variant="agent"
226	                      :copy-visible="agentHovered"
227	                      :popover-visible="agentHovered && agentTextHovered"
228	                      :auto-open-on-row-hover="false"
229	                      popover-placement="above"
230	                    />
231	                  </div>
232	                </div>
233	              </div>
234	            </div>
235	          </div>
236	        </div>
