// branching, so `scheduleNext` itself is a flat dispatch rather than one large state machine.

function scheduleIdle() {
  after(timings.startHoldMs, () => {
    activeIndex.value = (activeIndex.value + 1) % options.length;
    phase.value = "typing";
    scheduleNext();
